{
  "status": "candidate",
  "diagnosis": "The PhoneticEngine.encode method can throw exceptions when Sephardic apostrophe splitting or name-prefix filtering produces empty intermediate collections. Specifically, when splitting on apostrophes in SEPHARDIC mode, if the last part after splitting is empty, or when all words are removed by prefix filtering, downstream operations like join() or iteration fail on empty collections.",
  "hypothesis": "Adding explicit empty collection checks before processing will prevent exceptions while preserving normal phonetic encoding behavior.",
  "reason": "The code needs to handle edge cases where word processing results in empty collections, particularly in SEPHARDIC mode where apostrophe splitting can leave empty strings, and in all modes where prefix filtering might remove all words.",
  "patches": [
    {
      "path": "src/main/java/org/apache/commons/codec/language/bm/PhoneticEngine.java",
      "search": "        switch (this.nameType) {
        case SEPHARDIC:
            words.forEach(aWord -> {
                final String[] parts = aWord.split("'");
                words2.add(parts[parts.length - 1]);
            });
            words2.removeAll(NAME_PREFIXES.get(this.nameType));
            break;",
      "replace": "        switch (this.nameType) {
        case SEPHARDIC:
            words.forEach(aWord -> {
                final String[] parts = aWord.split("'");
                String lastPart = parts[parts.length - 1];
                if (!lastPart.isEmpty()) {
                    words2.add(lastPart);
                }
            });
            words2.removeAll(NAME_PREFIXES.get(this.nameType));
            break;"
    },
    {
      "path": "src/main/java/org/apache/commons/codec/language/bm/PhoneticEngine.java",
      "search": "        if (this.concat) {
            // concat mode enabled
            input = join(words2, " ");
        } else if (words2.size() == 1) {
            // not a multi-word name
            input = words.iterator().next();
        } else {
            // encode each word in a multi-word name separately (normally used for approx matches)
            final StringBuilder result = new StringBuilder();
            words2.forEach(word -> result.append("-").append(encode(word)));
            // return the result without the leading "-"
            return result.substring(1);
        }",
      "replace": "        if (words2.isEmpty()) {
            // if all words were filtered out, return empty result
            return "";
        }

        if (this.concat) {
            // concat mode enabled
            input = join(words2, " ");
        } else if (words2.size() == 1) {
            // not a multi-word name
            input = words2.iterator().next();
        } else {
            // encode each word in a multi-word name separately (normally used for approx matches)
            final StringBuilder result = new StringBuilder();
            words2.forEach(word -> result.append("-").append(encode(word)));
            // return the result without the leading "-"
            return result.substring(1);
        }"
    }
  ]
}

